args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-remaining-maps/transport');suppressPackageStartupMessages({library(sf);library(ggplot2);library(patchwork);library(grid)})
sf_use_s2(FALSE);set.seed(20261029)
wr<-function(x,p)jsonlite::write_json(x,p,auto_unbox=TRUE,pretty=TRUE,digits=NA)
pts<-function(g,n){q<-st_transform(st_make_valid(st_union(g)),3857);st_transform(st_sample(q,n,exact=TRUE),4326)}
xy<-function(g){d<-as.data.frame(st_coordinates(g));names(d)[1:2]<-c('x','y');d}
edges<-function(n,k=3){d<-as.matrix(dist(n[,c('x','y')]));diag(d)<-Inf;i<-rep(seq_len(nrow(n)),each=k);j<-unlist(lapply(seq_len(nrow(n)),function(j)order(d[j,])[1:k]));z<-unique(data.frame(i=pmin(i,j),j=pmax(i,j)));z$x<-n$x[z$i];z$y<-n$y[z$i];z$xend<-n$x[z$j];z$yend<-n$y[z$j];z}
th<-theme_void(base_family='Arial',base_size=7)+theme(legend.position='bottom',legend.text=element_text(size=7),legend.title=element_text(size=7),plot.title=element_text(size=7,face='bold'),plot.tag=element_text(size=8,face='bold'),strip.text=element_text(size=7),plot.margin=margin(2,2,2,2))
finish<-function(mid,p,stem,width,height,scope,geom,panels){w<-file.path(W,mid);dir.create(w,showWarnings=FALSE);saveRDS(p,file.path(w,'plot.rds'));ggsave(file.path(w,'exploratory.png'),p,width=width,height=height,units='mm',dpi=160,device=ragg::agg_png,bg='white');ragg::agg_png(file.path(w,'grob-measurement.png'),width=width,height=height,units='mm',res=160,background='white');g<-if(inherits(p,'patchwork'))patchworkGrob(p)else ggplotGrob(p);labels<-character();sizes<-numeric();fix<-function(x){if(inherits(x,'text')){x$gp$fontfamily<-'Arial';if(!is.null(x$gp$fontsize)){x$gp$fontsize<-pmax(7,x$gp$fontsize);sizes<<-c(sizes,x$gp$fontsize)};labels<<-c(labels,as.character(x$label))};if(length(x$grobs))x$grobs<-lapply(x$grobs,fix);if(length(x$children))x$children<-do.call(gList,lapply(x$children,fix));x};g<-fix(g);dev.off();saveRDS(g,file.path(w,'composed-vector-grob.rds'));saveRDS(ggplotify::as.ggplot(g)+theme(text=element_text(family='Arial',size=7),plot.margin=margin(0,0,0,0)),file.path(w,'render-object.rds'));wr(list(labels=unique(labels[nzchar(labels)]),point_sizes=sort(unique(sizes))),file.path(w,'text-manifest.json'));wr(list(stem=stem,width_mm=width,height_mm=height,panel_count=panels,simulation=TRUE,seed=20261029,data_origin=paste('User-authorized STRUCTURE PRACTICE ONLY. Fixed-seed synthetic values and positions; not author study data.',scope),geometry_crs=geom,palette='Source-guided categorical or ordered quantitative palette; independent legends preserve distinct meanings.'),file.path(w,'input-qc.json'));cat(mid,'PREPARED\n')}
export<-function(z,stem){write.csv(z,file.path(P,'results/plot_data',paste0(stem,'_20261029.csv')),row.names=FALSE)}
k<-st_read(file.path(W,'gadm41_KOR.gpkg'),layer='ADM_ADM_1',quiet=TRUE);k<-st_transform(st_simplify(st_transform(k,5179),dTolerance=200,preserveTopology=TRUE),4326)
# V01: actual country/province geography, synthetic city-node and weighted-flow fixture.
n<-xy(pts(k,250));n$id<-seq_len(nrow(n));n$community<-factor(kmeans(scale(n[,c('x','y')]),centers=7,nstart=15)$cluster);n$attractiveness<-round(exp(runif(nrow(n),log(1),log(1e5))));e<-edges(n,7);e$community<-ifelse(n$community[e$i]==n$community[e$j],as.character(n$community[e$i]),'between');e$weight<-exp(runif(nrow(e),0,5));e$within<-e$community!='between';export(n,'asf01_synthetic_nodes');export(e,'asf01_synthetic_edges');pal<-setNames(c('#D12DAC','#F4A62A','#5AA875','#66C5DF','#DA3322','#E9D91A','#3A5E99'),as.character(1:7));pal<-c(pal,between='#D4D7DB')
p<-ggplot()+geom_sf(data=k,fill='#F7F8F8',colour='#59646C',linewidth=.2)+geom_segment(data=e,aes(x,y,xend=xend,yend=yend,colour=community,linewidth=weight),alpha=.42)+scale_linewidth_continuous(range=c(.1,.65),guide='none')+scale_colour_manual(values=pal,breaks=as.character(1:7),name='Community')+geom_point(data=n,aes(x,y,fill=community,size=attractiveness),colour='#30343B',stroke=.25,shape=21,alpha=.85)+scale_fill_manual(values=pal,guide='none')+scale_size_continuous(trans='log10',range=c(.45,2.9),breaks=c(10,1000,50000),labels=c('10','1,000','50,000'),name='Node weight')+coord_sf(xlim=c(124.5,131.2),ylim=c(32.8,38.8),crs=4326,datum=NA)+th+theme(legend.position='right',legend.box='vertical')
finish('ASF-V01',p,'asf01_korea_network_structure',136,142,'250 synthetic nodes; nearest-neighbour edges and7 geographic clusters; node-size scale uses log10weights. No original destination IDs, tourist counts, community assignments or modularity claimed.','EPSG:4326, GADM4.1 KOR17 province outlines',1)
# V02: geographic service-area choropleth small multiples from real municipal outlines.
cities<-st_read(file.path(W,'gadm41_KOR.gpkg'),layer='ADM_ADM_2',quiet=TRUE);citynames<-c('Gangneung','Jeonju','Chuncheon');geo<-lapply(citynames,function(nm){g<-st_transform(cities[cities$NAME_2==nm,],3857);st_make_valid(st_union(g))});names(geo)<-citynames
panels<-data.frame(city=c('Gangneung','Gangneung','Jeonju','Jeonju','Chuncheon','Chuncheon','Chuncheon'),activity=c('C1 NAP','C1 OTHERS','C1 NAP','C1 OTHERS','C1 NAP','C1 OTHERS','C11 OTHERS'));plots<-list();tab<-list();cache<-list();geoout<-list()
for(i in 1:7){g<-geo[[panels$city[i]]];if(is.null(cache[[panels$city[i]]])){sites<-st_sample(g,90,exact=TRUE);cells<-st_collection_extract(st_voronoi(st_union(sites)));cells<-suppressWarnings(st_intersection(st_sf(cell_id=seq_along(cells),geometry=cells),st_sf(geometry=g)));cache[[panels$city[i]]]<-cells};cells<-cache[[panels$city[i]]];val<-rgamma(nrow(cells),shape=.2,rate=1);cells$activity_percent<-100*val/sum(val);cells$panel<-LETTERS[i];cells$city<-panels$city[i];geoout[[i]]<-cells;tab[[i]]<-st_drop_geometry(cells);q<-ggplot()+geom_sf(data=cells,aes(fill=activity_percent),colour='white',linewidth=.07)+geom_sf(data=st_sf(geometry=g),fill=NA,colour='#76818A',linewidth=.2)+scale_fill_gradientn(colours=c('#FFF6C5','#FFDB7B','#F9A13B','#E74338'),limits=c(0,8),oob=scales::squish,name='Activity share (%)',breaks=c(0,2,4,8),labels=c('0','2','4','>=8'),guide=guide_colourbar(direction='horizontal',title.position='top',barwidth=unit(30,'mm'),barheight=unit(3,'mm')))+coord_sf(datum=NA)+labs(title=paste0('(',LETTERS[i],') ',panels$city[i],' | ',panels$activity[i]))+th;plots[[i]]<-q}
export(do.call(rbind,tab),'asf02_synthetic_activity_cells');geoout<-do.call(rbind,geoout);gp<-file.path(P,'results/plot_data/asf02_synthetic_activity_geometry_20261029.gpkg');if(file.exists(gp))unlink(gp);st_write(geoout,gp,quiet=TRUE);p<-wrap_plots(c(plots,list(guide_area())),ncol=4,guides='collect')&theme(legend.position='bottom')
finish('ASF-V02',p,'asf02_korea_activity_map_structure',183,112,'Seven real-city maps in4+3 layout;90 synthetic Voronoi service-area cells per map and synthetic percent shares; display is saturated at>=8%. Original MBS coordinates, activity shares and inferential hotspots are unavailable; no confidence or hotspot-significance claims.','GADM4.1 KORADM2 municipal outlines; Voronoi calculations EPSG:3857',7)
# V04: matched oblique3D bar maps over actual Singapore outline.
sg<-st_read(file.path(W,'gadm41_SGP.gpkg'),layer='ADM_ADM_0',quiet=TRUE);sg<-st_transform(sg,3414);bc<-st_coordinates(sg);border<-data.frame(x=bc[,1]/1000,y=bc[,2]/1000,group=interaction(bc[,3],bc[,4],bc[,5]));sample<-st_sample(st_union(sg),650,exact=TRUE);nn<-as.data.frame(st_coordinates(sample)/1000);names(nn)<-c('x','y');dd<-do.call(rbind,lapply(c('Weekday','Weekend'),function(day){d<-nn;d$day<-day;d$arrivals<-round(pmin(100,rgamma(nrow(d),shape=.7,rate=.022)));d}));dd$px<-dd$x+.45*dd$y;dd$py<-.58*dd$y;dd$top<-dd$py+dd$arrivals*.065;border$px<-border$x+.45*border$y;border$py<-.58*border$y;export(dd,'asf04_synthetic_arrival_bars')
p<-ggplot()+geom_polygon(data=border,aes(px,py,group=group),fill='#E0E5E7',colour='#A5AFB5',linewidth=.1)+geom_segment(data=dd,aes(px,py,xend=px,yend=top,colour=arrivals),linewidth=.7,lineend='round')+scale_colour_gradientn(colours=c('#087EA4','#1BB89B','#F6D76B','#F29C38','#C82856'),limits=c(0,100),name='Average daily arrival trips',breaks=c(0,20,40,60,80,100))+facet_wrap(~day,nrow=1)+coord_equal()+th+theme(panel.background=element_rect(fill='white',colour=NA),strip.background=element_rect(fill='white',colour=NA),strip.text=element_text(colour='#17232A',size=7),panel.spacing=unit(1,'mm'))
finish('ASF-V04',p,'asf04_singapore_oblique_map_structure',183,78,'Two matched oblique views using650 synthetic locations each. Oblique projectionx=x+.45y,y=.58y; column height encodes synthetic0-100 arrivals. Actual2017bikeGPS and per-cell arrival values unavailable. White panels replace original dark basemap because core background policy permits noV04dark-panel exception.','GADM4.1 SGP; EPSG:3414 projected kilometres and declared oblique display transform',2)
# V26: real Wuhan district boundaries, synthetic path-count network in9 time windows.
wh<-st_read(file.path(W,'wuhan_districts.geojson'),quiet=TRUE);wh<-st_transform(wh,4326);wh<-st_make_valid(wh);n<-xy(pts(wh,240));e<-edges(n,3);base<-e;windows<-sprintf('[%02d:00,%02d:00]',seq(6,22,2),seq(8,24,2));a<-runif(nrow(e));d<-do.call(rbind,lapply(seq_along(windows),function(i){q<-e;q$window<-windows[i];q$paths<-pmax(1,pmin(200,round(220*(a^3)*c(.25,.7,1,.95,.9,.55,.8,.1,.45)[i])));q$class<-cut(q$paths,c(0,10,20,40,80,200),labels=c('1-10','11-20','21-40','41-80','81-200'),include.lowest=TRUE);q}));export(d,'asf26_synthetic_path_windows');p<-ggplot()+geom_sf(data=wh,fill='#FBFCFC',colour='#C6CDD0',linewidth=.1)+geom_segment(data=base,aes(x,y,xend=xend,yend=yend),colour='#DCE1E3',linewidth=.15)+geom_segment(data=d,aes(x,y,xend=xend,yend=yend,colour=class,linewidth=class),alpha=.9)+scale_colour_manual(values=c('#1663C7','#EA4C17','#C3B51B','#238762','#D51E36'),name='Paths')+scale_linewidth_manual(values=c(.18,.3,.45,.7,.95),name='Paths')+facet_wrap(~window,ncol=3)+coord_sf(datum=NA)+th+theme(strip.background=element_blank())
finish('ASF-V26',p,'asf26_wuhan_time_maps_structure',136,165,'Nine2-hour maps with synthetic nearest-neighbour path network and fixed synthetic path counts. Actual taxi tracks, bridge alternative-path assignments and road-level values unavailable. Network segments are synthetic geometry, not observed Wuhan roads.','Wuhan district GeoJSON from Alibaba DataV; EPSG:4326; actual administrative outline only',9)
# V27: actual US Census county outlines, synthetic paired network flows and zooms.
us<-st_read(file.path(P,'work/2026-10-29-remaining-maps/mobility/census-2017-counties/cb_2017_us_county_500k.shp'),quiet=TRUE);ma<-st_transform(us[us$STATEFP%in%c('25','33'),],4326);ma<-suppressWarnings(st_crop(ma,c(xmin=-72.1,xmax=-70.4,ymin=41.5,ymax=43.0)));n<-xy(pts(ma,450));e<-edges(n,3);e$countA<-pmax(1,round(exp(runif(nrow(e),log(500),log(30000)))));e$countB<-pmax(1,round(e$countA*runif(nrow(e),.65,1.35)));export(e,'asf27_synthetic_boston_flows');br<-c(0,1000,5000,10000,25000,Inf);lev<-c('<1,000','1,000-5,000','5,000-10,000','10,000-25,000','>25,000');e$a<-cut(e$countA,br,labels=lev);e$b<-cut(e$countB,br,labels=lev);mp<-function(field,xr,yr,tag){q<-e;q$flow<-q[[field]];ggplot()+geom_sf(data=ma,fill='#F2F3F4',colour='#CBD0D4',linewidth=.1)+geom_segment(data=q,aes(x,y,xend=xend,yend=yend,colour=flow,linewidth=flow),alpha=.78)+scale_colour_manual(values=c('#DBCFEB','#BA96D5','#9564B4','#743C96','#4D226C'),name='Home-work trips')+scale_linewidth_manual(values=c(.1,.2,.35,.55,.8),name='Home-work trips')+coord_sf(xlim=xr,ylim=yr,datum=NA,expand=FALSE)+labs(tag=tag)+th}
p<-wrap_plots(A=mp('a',c(-72.1,-70.4),c(41.5,43),'a'),B=mp('b',c(-72.1,-70.4),c(41.5,43),'b'),C=mp('a',c(-71.3,-70.7),c(42.1,42.65),'c'),D=mp('b',c(-71.3,-70.7),c(42.1,42.65),'d'),design='ABC\nABD',widths=c(1,1,.8),guides='collect')&theme(legend.position='bottom')
finish('ASF-V27',p,'asf27_boston_network_zoom_structure',183,112,'Two synthetic home-work flow scenarios plus matched detail crops.2017 Census county geometry provides geographic context; all network nodes, straight segments and trip counts are simulated, not the authors2010CDR/CTPS traffic assignments.','US Census2017 county polygons EPSG:4269 transformed EPSG:4326',4)
